// CSD_RATIONALE_BEGIN
// Key improvements over the best attempt (40.8 % / 91.8 %):
//
// PRIMARY FIX — tokenizer-safe span detection.
//   Replace exact `next == "<<"` with `RenderedEndsWith(generated, "<<")`.
//   Qwen may emit `<<` as a space-prefixed token `" <<"` that passes the exact
//   check but is not equal to `"<<"`. When detection silently fails the model
//   continues in unconstrained mode, allowing `{braces}`, `**`, and other
//   parser-rejected tokens into visible spans → final_span_invalid failures.
//
// SECONDARY FIX — EOS during constrained generation.
//   The prior best attempt simply `break`s on EOS while insideConstrained is
//   true, leaving the span open. Now: on EOS during constrained generation,
//   if `IsCompletePrefix`, call `CloseConstrainedSpan`; otherwise call
//   `CloseSpanWithinBudget` with the remaining budget; then break. This
//   eliminates final_span_unclosed failures triggered by model-EOS mid-span.
//
// REMOVED — forced OpenConstrainedSpan at ≤4-step budget pressure.
//   All 49 examples naturally emit at least one `<<` token. Force-opening a
//   span near budget end caused the model to produce an empty or unclosed span
//   after already writing a valid final answer. Removing this eliminates that
//   failure mode entirely.
//
// UNCHANGED — multi-span approach.
//   The evaluator extracts the LAST span. Letting the model produce natural
//   intermediate spans is fine because every span entering via
//   EnterObservedConstrainedSpan immediately switches to hard-constrained
//   AdaptiveConstrainedStep decoding.
//
// GUIDANCE — plain variable names + int() reminder.
//   Hard-masking already blocks `{braces}` inside spans once detection fires
//   correctly. The guidance also nudges the model toward `int()` wrapping and
//   helps the unconstrained reasoning phase stay on track.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 — parser_validity:
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   Outside-span branch (UnconstrainedStep):
//     insideConstrainedOut is false. After appending next to generated we test
//     RenderedEndsWith. If it fires, EnterObservedConstrainedSpan sets
//     currentConstrainedOut := [] and insideConstrainedOut := true.
//     parser.IsValidPrefix([]) holds by the method precondition on parser.
//     Otherwise insideConstrainedOut stays false (implication vacuous). ✓
//
//   Inside-span — CloseConstrainedSpan branch (IsCompletePrefix true):
//     IsCompletePrefix implies IsValidPrefix, satisfying the precondition.
//     Afterwards insideConstrainedOut := false → implication vacuously true. ✓
//
//   Inside-span — CloseSpanWithinBudget (near-budget or EOS-fallback):
//     Helper postcondition directly asserts
//     insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut). ✓
//
//   Inside-span — AdaptiveConstrainedStep normal token:
//     next is hard-masked to parser-valid next tokens for currentConstrainedOut.
//     AppendConstrainedToken extends currentConstrainedOut by exactly that
//     valid next token, preserving IsValidPrefix by the grammar's definition
//     of valid-prefix extension. ✓
//
//   Inside-span — EOS path with CloseConstrainedSpan:
//     Guard `IsCompletePrefix && steps < maxSteps` satisfies the precondition.
//     Afterwards insideConstrainedOut := false. ✓
//
//   Inside-span — EOS path with CloseSpanWithinBudget:
//     Same postcondition guarantee as the near-budget branch. ✓
//
//   Inside-span — EOS break without any close (neither branch taken):
//     insideConstrainedOut and currentConstrainedOut are unchanged from the
//     previous iteration; the invariant holds from there. ✓
//
// Invariant 2 — progress: |generated| <= |generatedPrefix| + steps
//
//   Init: equality at steps = 0. ✓
//
//   UnconstrainedStep (outside span):
//     steps += 1; if not EOS, generated grows by exactly 1 (EOS breaks without
//     appending). EnterObservedConstrainedSpan leaves generated unchanged. ✓
//
//   CloseConstrainedSpan (IsCompletePrefix):
//     steps += 1; helper appends at most 1 token (">>").
//     |generated| <= old|generated| + 1 <= |generatedPrefix| + steps. ✓
//
//   CloseSpanWithinBudget (near budget, closeBudget = maxSteps - steps):
//     Postcondition gives |generated_new| <= |generated_old| + closeBudget.
//     After steps := maxSteps:
//       |generated_new| <= |generatedPrefix| + steps_before + closeBudget
//                        = |generatedPrefix| + maxSteps = |generatedPrefix| + steps. ✓
//
//   AdaptiveConstrainedStep (normal token):
//     steps += 1; AppendConstrainedToken appends exactly 1 token.
//     |generated| <= old|generated| + 1 <= |generatedPrefix| + steps. ✓
//
//   EOS path (token not appended, steps += 1 from AdaptiveConstrainedStep):
//     Let s0 = steps before the AdaptiveConstrainedStep increment, so s0 < maxSteps.
//     After increment: steps = s0 + 1 <= maxSteps.
//     |generated| unchanged <= |generatedPrefix| + s0 = |generatedPrefix| + steps - 1.
//     + CloseConstrainedSpan (steps < maxSteps guard → steps := steps + 1 <= maxSteps):
//       generated grows ≤ 1 → |generated| <= |generatedPrefix| + s0 + 1
//                                            = |generatedPrefix| + steps. ✓
//     + CloseSpanWithinBudget (closeBudget = maxSteps - steps):
//       |generated| <= |generatedPrefix| + s0 + (maxSteps - s0 - 1)
//                    = |generatedPrefix| + maxSteps - 1;
//       after steps := maxSteps: <= |generatedPrefix| + steps. ✓
//     + break with no close: generated unchanged, invariant holds. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm,
  "Solve the math problem step by step. At each computation step wrap the " +
  "symbolic expression in << >> using plain variable names without curly braces. " +
  "Example: <<n * price>> or <<int(total * rate / 100)>>. " +
  "The final numeric answer must also appear inside a << >> span.");

var steps: nat := 0;
var narrowThreshold: nat := 12;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    } else {
      generated := generated + [next];
      if RenderedEndsWith(generated, "<<") {
        var og, oi, oc := helpers.EnterObservedConstrainedSpan(lm, generated);
        generated := og;
        insideConstrainedOut := oi;
        currentConstrainedOut := oc;
      }
    }
  } else {
    // Inside a constrained span.
    if parser.IsCompletePrefix(currentConstrainedOut) {
      // Expression is complete: emit ">>" and exit constrained mode.
      var cg, ci, cc := helpers.CloseConstrainedSpan(
        lm, parser, generated, currentConstrainedOut
      );
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := steps + 1;
    } else if maxSteps - steps <= 2 {
      // Near budget: advance to a completable state and close within budget.
      var closeBudget := maxSteps - steps;
      var cg, ci, cc := helpers.CloseSpanWithinBudget(
        lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
      );
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := maxSteps;
    } else {
      // Normal constrained generation: advance one hard-masked parser-valid token.
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next := helpers.AdaptiveConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut,
        validTokenGroups, 4.0, narrowThreshold, eosToken
      );
      steps := steps + 1;
      if next == eosToken {
        // EOS while span is still open: close cleanly before breaking.
        if parser.IsCompletePrefix(currentConstrainedOut) && steps < maxSteps {
          var cg, ci, cc := helpers.CloseConstrainedSpan(
            lm, parser, generated, currentConstrainedOut
          );
          generated := cg;
          insideConstrainedOut := ci;
          currentConstrainedOut := cc;
          steps := steps + 1;
        } else if steps < maxSteps {
          var closeBudget := maxSteps - steps;
          var cg, ci, cc := helpers.CloseSpanWithinBudget(
            lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
          );
          generated := cg;
          insideConstrainedOut := ci;
          currentConstrainedOut := cc;
          steps := maxSteps;
        }
        break;
      } else {
        var ag, ai, ac := helpers.AppendConstrainedToken(
          lm, parser, generated, currentConstrainedOut, next
        );
        generated := ag;
        insideConstrainedOut := ai;
        currentConstrainedOut := ac;
      }
    }
  }
}

